"use client";

import { forwardRef, type ButtonHTMLAttributes } from "react";

export type ToggleProps = ButtonHTMLAttributes<HTMLButtonElement> & { pressed: boolean; onPressedChange?: (pressed: boolean) => void };
export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(({ pressed, onPressedChange, className = "", onClick, ...props }, ref) => <button ref={ref} type="button" aria-pressed={pressed} className={`co-inline-flex co-h-10 co-items-center co-justify-center co-rounded-md co-px-3 co-text-sm co-font-medium focus-visible:co-ring-2 disabled:co-opacity-50 ${pressed ? "co-bg-black co-text-white" : "co-bg-transparent hover:co-bg-black/5"} ${className}`.trim()} onClick={(event) => { onPressedChange?.(!pressed); onClick?.(event); }} {...props} />);
Toggle.displayName = "Toggle";
